import {readFileSync,readdirSync,existsSync,writeFileSync} from 'node:fs';
import {createHash} from 'node:crypto';
import {spawnSync} from 'node:child_process';
import {isDeepStrictEqual as equal} from 'node:util';
const output='.agentdoc/v07-setup-20260911T122653Z/evidence/release-v070-analysis';
const root='.agentdoc/v07-setup-20260911T122653Z/evidence/measurement-release-v070';
const reportPath='.agentdoc/v07-setup-20260911T122653Z/evidence/release.json';
if(process.env.DESMON_RELEASE_COMPLETE!=='release-v070')throw Error('Wait for Host COMPLETE notice; validation data access not authorized yet.');
const read=p=>JSON.parse(readFileSync(p,'utf8')),hash=b=>createHash('sha256').update(b).digest('hex'),fileHash=p=>hash(readFileSync(p)),objectHash=o=>hash(JSON.stringify(o));
const prep=read(output+'/preparation.json');
const executionPath=root+'/execution.json',execution=read(executionPath);
if(!execution.endedAt)throw Error('Incomplete execution: no report/raw/log/archive access.');
const errors=[],check=(ok,label)=>{if(!ok)errors.push(label);};
const protocolPath=root+'/protocol.adopted.json',protocol=read(protocolPath);
check(fileHash(protocolPath)===prep.protocol.sha256,'exact adopted protocol bytes');
check(equal(execution.protocol,{path:protocolPath,sha256:prep.protocol.sha256}),'execution adopted protocol binding');
check(protocol.round===8&&protocol.schemaVersion===2&&protocol.progressionParameterVersion===3&&protocol.phase==='candidate'&&protocol.experimentStage==='validation','protocol stage/version');
check(equal(protocol.selectedExperiment,prep.selectedExperiment)&&equal(execution.experiment,prep.selectedExperiment),'frozen selected experiment');
check(Date.parse(protocol.frozenAt)<=Date.parse(execution.startedAt)&&Date.parse(protocol.adoption.at)<=Date.parse(execution.startedAt),'adoption precedes execution');
check(fileHash(prep.script.path)===prep.script.sha256,'validation execution script unchanged');
check(fileHash(prep.completedDesign.path)===prep.completedDesign.sha256,'completed design session unchanged');
const completedDesign=read(prep.completedDesign.path);
check(completedDesign.status==='design_review_complete'&&completedDesign.round===2&&completedDesign.openFindings.length===0&&completedDesign.sourceDigest===prep.hostExpected.sourceDigest&&completedDesign.evaluationDigest===prep.hostExpected.evaluationDigest,'completed actual fun matches final S/E');
for(const r of prep.completedDesign.reports){
 check(fileHash(r.path)===r.sha256,'actual final role response '+r.role);
 const actual=read(r.path);check(actual.decision==='pass'&&actual.round===2&&actual.role===r.role&&actual.agent===r.agent&&actual.requestId===r.requestId&&actual.sourceDigest===prep.hostExpected.sourceDigest&&actual.evaluationDigest===prep.hostExpected.evaluationDigest&&completedDesign.history.some(h=>equal(h.report,actual)),'completed role binding '+r.role);
}

check(execution.appVersion==='0.7.0','final version explicitly0.7.0');
check(equal(execution.seedSet,{name:'validation',start:1,count:100}),'execution validation seed set');
for(const key of ['preregisteredProtocol','independentAnalysis','hostCheck']){
 const a=protocol.adoption[key];check(a&&fileHash(a.path)===a.sha256,'preserved adoption artifact '+key);
}
const report=read(reportPath);
check(report.rawComplete===true&&report.phase==='release'&&report.seedSet==='validation'&&report.screening===false,'complete release suite report');
check(equal(report.seeds,{start:1,count:100})&&report.runs.length===900,'full900 release samples');
check(equal(report.protocol,protocol)&&report.protocolSha256===objectHash(protocol),'embedded adopted protocol binding');
check(equal(execution.report,{path:reportPath,sha256:fileHash(reportPath)}),'execution report file hash');
for(const k of ['sourceDigest','evaluationDigest','rawSha256','targets'])check(equal(execution[k],report[k]),'execution report '+k);
check(report.sourceDigest===prep.hostExpected.sourceDigest&&report.evaluationDigest===prep.hostExpected.evaluationDigest,'Host declared exact final S/E');
check(report.rawSha256===objectHash(report.runs),'report raw object hash');
check(report.fixture===null&&report.fixtureSha256===objectHash(null),'fresh fixture');
check(equal(report.settings,prep.measurementSettings),'frozen measurement settings including9 policy definitions');
const canonical=prep.measurementSettings.baseline;
const policies=prep.measurementSettings.validationPolicies;
check(equal(report.policies,policies)&&equal(execution.policies,policies)&&policies.length===9,'exact9 release policies');
for(const policy of policies)check(equal(report.runs.filter(r=>equal(r.policy,policy)).map(r=>r.seed).sort((a,b)=>a-b),Array.from({length:100},(_,i)=>i+1)),'each policy has exact100 distinct validation seeds');
check(equal(report.checkpointsMinutes,prep.measurementSettings.checkpointsMinutes)&&report.timing.modeledMinutes===720,'full12h checkpoints');
const experiment=protocol.candidates.find(e=>e.id===protocol.selectedExperiment.id);
check(experiment&&equal(experiment.parameters,prep.parameters)&&Object.keys(experiment.parameters).length===21,'registered21 selected parameters');
check(report.experiment.kind==='candidate'&&report.experiment.id===prep.selectedExperiment.id&&report.experiment.parametersSha256===objectHash(experiment.parameters),'report parameter binding');
const contentRules=Object.fromEntries(protocol.milestones.flatMap(m=>m.ids.map(id=>[id,m.requirements])));
check(report.experiment.contentRulesSha256===objectHash(contentRules)&&equal(protocol.milestones,prep.milestones),'six frozen content requirements');
const expectedCommands=[
 ['measure',['node','.harness/v7/loop/measure.mjs','run',reportPath,'--phase','release','--suite','--candidate',prep.selectedExperiment.id,'--seed-set','validation','--workers','4']],
 ['structural-verify',['node','.harness/v7/loop/measure.mjs','verify',reportPath]]
];
check(execution.commands.length===2,'two execution commands');
for(const [index,command] of execution.commands.entries()){
 const expected=expectedCommands[index];check(expected&&command.label===expected[0]&&equal(command.argv,expected[1]),'exact command '+index);
 check(command.log&&fileHash(command.log.path)===command.log.sha256,'command log hash '+index);
 check(Date.parse(command.startedAt)>=Date.parse(execution.startedAt)&&Date.parse(command.endedAt)<=Date.parse(execution.endedAt),'command chronology '+index);
 check(command.exitCode===(index===0?(report.targets.passed?0:1):0),'command exit matches actual target/structural '+index);
}
const readinessOrder=['progression','harness','measurement','gates','integration','gates'];
check(equal(execution.readinessChecks.map(c=>c.commandId),readinessOrder),'six V05/V06 readiness checks');
for(const [i,c] of execution.readinessChecks.entries()){
 check(c.exitCode===0&&c.sourceDigest===report.sourceDigest&&c.endedDigest===report.sourceDigest&&c.evaluationDigest===report.evaluationDigest&&c.endedEvaluationDigest===report.evaluationDigest,'same S/E preflight '+i);
 check(fileHash(c.log)===c.sha256,'preflight log hash '+i);
 check(equal(c.filesHash,c.endedFilesHash)&&equal(c.filesHash,prep.ownedFileManifests[i<4?'V07-05':'V07-06']),'owned source/tests unchanged '+i);
}
const archiveCache=new Map(),archiveInfo=[];
function archive(path){
 if(archiveCache.has(path))return archiveCache.get(path);
 const py='import tarfile,hashlib,json,sys,pathlib\nwith tarfile.open(sys.argv[1]) as t:\n ms=t.getmembers(); names=[m.name for m in ms]\n assert len(names)==len(set(names))\n assert all(not pathlib.PurePosixPath(n).is_absolute() and ".." not in pathlib.PurePosixPath(n).parts for n in names)\n assert all(m.isfile() or m.isdir() for m in ms)\n print(json.dumps({m.name:hashlib.sha256(t.extractfile(m).read()).hexdigest() for m in ms if m.isfile()}))';
 const res=spawnSync('python3',['-c',py,path],{encoding:'utf8'});if(res.status!==0)throw Error(res.stderr);
 const files=JSON.parse(res.stdout);archiveCache.set(path,files);archiveInfo.push({path,sha256:fileHash(path),fileMembers:Object.keys(files).length,uniqueSafePaths:true});return files;
}
function archiveText(path,member){
 const py='import tarfile,sys\nwith tarfile.open(sys.argv[1]) as t: sys.stdout.write(t.extractfile(sys.argv[2]).read().decode())';
 const res=spawnSync('python3',['-c',py,path,member],{encoding:'utf8'});if(res.status!==0)throw Error(res.stderr);return res.stdout;
}
function exportedParameters(text){
 const body=text.match(/PROGRESSION_PARAMETERS[^=\n]*=\s*Object\.freeze\(\{([\s\S]*?)\}\)/)?.[1];
 if(!body)throw Error('Missing actual frozen progression object');
 return JSON.parse('{'+body.replace(/^(\s*)([A-Za-z]\w*)(\s*:)/gm,'$1"$2"$3').replace(/,\s*$/,'')+'}');
}
for(const k of ['sourceArchive','evaluationArchive','buildArchive'])check(execution[k]&&fileHash(execution[k].path)===execution[k].sha256,k+' literal hash');
const src=archive(execution.sourceArchive.path),ev=archive(execution.evaluationArchive.path),build=archive(execution.buildArchive.path);
for(const [p,h] of Object.entries({...prep.ownedFileManifests['V07-05'],...prep.ownedFileManifests['V07-06']})){
 if(p==='README.md')check(fileHash(prep.readmeSnapshot.path)===h&&h===prep.readmeSnapshot.sha256,'separate owned README snapshot (not source digest)');
 else check((p.startsWith('.harness/')||p.startsWith('docs/')?ev[p]:src[p])===h,'archived owned source/test binding '+p);
}
check(Object.keys(src).every(p=>!p.startsWith('Users/')),'root-relative source including tsconfigs');
const sourceFiles=Object.fromEntries(Object.entries(src).filter(([p])=>p.startsWith('src/')||p.startsWith('static/')||/^(package(-lock)?|tsconfig[^/]*)\.json$/.test(p)));
check(hash(Object.keys(sourceFiles).sort().map(p=>p+'\0'+sourceFiles[p]).join('\n'))===report.sourceDigest,'archived source digest');
const evaluationFiles=Object.fromEntries(Object.entries(ev).filter(([p])=>p.startsWith('.harness/v7/')||p==='docs/v0.7/EVALUATION_PROTOCOL.json'));
check(hash(Object.entries(evaluationFiles).sort(([a],[b])=>a.localeCompare(b)).map(([p,h])=>p+'\0'+h).join('\n'))===report.evaluationDigest,'archived evaluator digest');
check(ev['docs/v0.7/EVALUATION_PROTOCOL.json']===prep.protocol.sha256,'archived official protocol bytes');
check(report.build.sha256===objectHash(report.build.files),'build manifest hash');
for(const [p,h] of Object.entries(report.build.files))check(build[p]===h,'archived compiled file '+p);
const compiledPath=Object.keys(build).find(p=>p.endsWith('/core/progression.js'));
check(Boolean(compiledPath),'compiled progression exists');
const sourceParameters=exportedParameters(archiveText(execution.sourceArchive.path,'src/core/progression.ts'));
const compiledParameters=compiledPath?exportedParameters(archiveText(execution.buildArchive.path,compiledPath)):null;
check(equal(sourceParameters,experiment.parameters)&&equal(compiledParameters,experiment.parameters),'actual source and compiled21 parameter equality');
const packageInfo=JSON.parse(archiveText(execution.sourceArchive.path,'package.json')),lock=JSON.parse(archiveText(execution.sourceArchive.path,'package-lock.json'));
check(packageInfo.version==='0.7.0'&&lock.version==='0.7.0'&&lock.packages[''].version==='0.7.0','final package/lock actual version');

const manifestPath=reportPath+'.runs/manifest.json',manifest=read(manifestPath);
check(manifest.binding===objectHash(manifest.identity),'manifest binding');
for(const k of ['sourceDigest','evaluationDigest','protocolSha256','fixtureSha256','seedSet','seeds','policies','settings','screening','checkpointsMinutes','experiment'])check(equal(manifest.identity[k],report[k]),'manifest identity '+k);
check(manifest.identity.buildSha256===report.build.sha256,'manifest build binding');
const policyKey=p=>[p.profile,p.policy,p.inputSchedule,p.management,p.menuVisitSeconds].join('/');
const policyHash=p=>hash(policyKey(p)),runRoot=reportPath+'.runs';
const walk=dir=>readdirSync(dir,{withFileTypes:true}).flatMap(e=>e.isDirectory()?walk(dir+'/'+e.name):[dir+'/'+e.name]);
const expectedFiles=[manifestPath,...policies.flatMap(p=>Array.from({length:100},(_,i)=>runRoot+'/'+policyHash(p)+'/'+(i+1)+'.json'))];
check(equal(walk(runRoot).sort(),expectedFiles.sort()),'manifest1 plus exact900 raw files');
const popQ=(xs,q)=>{const sorted=[...xs].sort((a,b)=>(a??Infinity)-(b??Infinity));return sorted.length?sorted[Math.floor((sorted.length-1)*q)]:null;};
function stats(xs){
 check(xs.every(v=>v===null||typeof v==='number'&&Number.isFinite(v)),'finite statistics');
 const ys=xs.filter(v=>v!==null),quantiles=vs=>({p10:popQ(vs,.1),p50:popQ(vs,.5),p90:popQ(vs,.9),worst:popQ(vs,1)});
 return {samples:xs.length,reached:ys.length,unreached:xs.length-ys.length,population:quantiles(xs),conditional:quantiles(ys),minimum:ys.length?Math.min(...ys):null};
}
const firstNames=['firstKillSec','firstRewardSec','firstLevelSec','firstCaptureSec','firstReadySec','firstOpenSec','firstAcceptedSec'];
const numberFields=['level','kills','coins','income','spent','companions','maxCompanionLevel','reincarnations','training','offers','rerolls','managementActions','feverStarts','inputCount','longestKillGapSec','longestMeaningfulGapSec','longestDiscoveryGapSec','eligibleHeroCount','eligibleMonsterCount','seenHeroCount','seenMonsterCount','chosenHeroCount','killedMonsterCount','capturedMonsterCount'];
const event=(run,kind,id='')=>{const xs=run.records.filter(r=>r.kind===kind&&r.id===id);check(xs.length<=1,'unique first event '+run.seed+'/'+kind+'/'+id);return xs[0]?.sec??null;};
const tick=v=>{const t=Math.round(v*10);check(Math.abs(t/10-v)<1e-7,'100ms event precision');return t;};
const gap=(run,kinds)=>{const ts=[72000,...run.records.filter(r=>kinds.includes(r.kind)&&tick(r.sec)>=72000&&tick(r.sec)<=432000).map(r=>tick(r.sec)).sort((a,b)=>a-b),432000];return Math.max(...ts.slice(1).map((t,i)=>t-ts[i]))/10;};
const rawFiles=[],policyResults=[];
for(const policy of policies){
 const runs=report.runs.filter(r=>equal(r.policy,policy)),rows=[];
 for(const run of runs){
  const path=runRoot+'/'+policyHash(policy)+'/'+run.seed+'.json',raw=read(path);
  check(raw.binding===manifest.binding&&raw.sha256===objectHash(raw.run)&&equal(raw.run,run),'raw binding '+policyKey(policy)+'/'+run.seed);
  rawFiles.push({path,sha256:fileHash(path),runSha256:raw.sha256});
  check(Object.values(run.initial).every(v=>v===0),'fresh initial '+policyKey(policy)+'/'+run.seed);
  check(equal(run.checkpoints.map(c=>c.minutes),report.checkpointsMinutes),'all checkpoints '+run.seed);
  for(const cp of run.checkpoints){
   check(run.initial.coins+cp.income-cp.spent===cp.coins,'gold conservation '+policyKey(policy)+'/'+run.seed+'/'+cp.minutes);
   for(const n of ['coins','income','spent','level','kills','companions','maxCompanionLevel'])check(Number.isSafeInteger(cp[n])&&cp[n]>=0,'safe nonnegative checkpoint '+run.seed+'/'+n);
   for(const n of ['heroDamage','companionDamage','partyPower'])check(typeof cp[n]==='string'&&/^(0|[1-9][0-9]*)$/.test(cp[n]),'exact bigint '+run.seed+'/'+n);
  }
  let previous=-1;const seen=new Set();
  for(const rec of run.records){const t=tick(rec.sec),k=rec.kind+'/'+rec.id;check(t>=previous&&t>=0&&t<=432000&&!seen.has(k),'ordered unique record '+run.seed);previous=t;seen.add(k);}
  previous=-1;for(const action of run.actions){const t=tick(action.sec);check(t>=previous&&t>=0&&t<=432000,'ordered action '+run.seed);previous=t;}
  const last=run.checkpoints.at(-1),at8=run.checkpoints.find(c=>c.minutes===480);
  const row={seed:run.seed,...Object.fromEntries(firstNames.map(n=>[n,event(run,n)])),h70EligibleSec:event(run,'eligibleHero','h70'),h70SeenSec:event(run,'seenHero','h70'),h70ChosenSec:event(run,'chosenHero','h70')};
  for(const n of firstNames)check(last[n]===row[n],'first checkpoint '+run.seed+'/'+n);
  check(last.lastUnlockSec===row.h70EligibleSec,'h70 checkpoint '+run.seed);
  if(row.firstOpenSec!==null)check(row.firstReadySec!==null&&row.firstReadySec<=row.firstOpenSec,'ready/open '+run.seed);
  if(row.firstAcceptedSec!==null)check(row.firstOpenSec!==null&&row.firstOpenSec<=row.firstAcceptedSec,'open/accepted '+run.seed);
  row.readyToOpenSec=row.firstReadySec===null||row.firstOpenSec===null?null:(tick(row.firstOpenSec)-tick(row.firstReadySec))/10;
  row.openToAcceptedSec=row.firstOpenSec===null||row.firstAcceptedSec===null?null:(tick(row.firstAcceptedSec)-tick(row.firstOpenSec))/10;
  row.distinctChosenHeroIds=[...new Set(run.actions.filter(a=>a.type==='heroChoose').map(a=>a.formId))];
  check(row.distinctChosenHeroIds.length===last.chosenHeroCount,'actual chosen IDs '+run.seed);
  row.actionCounts=Object.fromEntries(['heroChoose','consume','fuse','reincarnate'].map(k=>[k,run.actions.filter(a=>a.type===k).length]));
  row.terminal=Object.fromEntries(numberFields.map(n=>[n,last[n]]));
  row.exact=Object.fromEntries(['heroDamage','companionDamage','partyPower'].map(n=>[n,last[n]]));
  row.paired8to12={...Object.fromEntries(['kills','reincarnations','chosenHeroCount','killedMonsterCount','seenHeroCount','seenMonsterCount','income','spent','managementActions'].map(n=>[n,last[n]-at8[n]])),heroChooseActions:run.actions.filter(a=>a.type==='heroChoose'&&tick(a.sec)>288000).length,partyPowerBefore:at8.partyPower,partyPowerAfter:last.partyPower,partyPowerDelta:(BigInt(last.partyPower)-BigInt(at8.partyPower)).toString()};
  row.gaps2to12={seenSec:gap(run,['seenHero','seenMonster']),acquiredSec:gap(run,['chosenHero','killedMonster'])};
  rows.push(row);
 }
 const metrics=Object.fromEntries([...firstNames,'h70EligibleSec','h70SeenSec','h70ChosenSec','readyToOpenSec','openToAcceptedSec'].map(n=>[n,stats(rows.map(r=>r[n]))]));
 const milestones=protocol.milestones.map(m=>({...m,eligible:stats(runs.map(r=>event(r,m.kind==='hero'?'eligibleHero':'eligibleMonster',m.id))),seen:stats(runs.map(r=>event(r,m.kind==='hero'?'seenHero':'seenMonster',m.id))),acquired:stats(runs.map(r=>event(r,m.kind==='hero'?'chosenHero':'killedMonster',m.id))),...(m.kind==='monster'?{captured:stats(runs.map(r=>event(r,'capturedMonster',m.id)))}:{})}));
 const checkpoints=report.checkpointsMinutes.map(minutes=>({minutes,metrics:Object.fromEntries(numberFields.map(n=>[n,stats(runs.map(r=>r.checkpoints.find(c=>c.minutes===minutes)[n]))]))}));
 const pairedFields=['kills','reincarnations','chosenHeroCount','killedMonsterCount','seenHeroCount','seenMonsterCount','income','spent','managementActions','heroChooseActions'];
 const paired8to12={metrics:Object.fromEntries(pairedFields.map(n=>[n,stats(rows.map(r=>r.paired8to12[n]))])),unchangedPartyPower:rows.filter(r=>r.paired8to12.partyPowerDelta==='0').length};
 const gaps2to12=Object.fromEntries(['seenSec','acquiredSec'].map(n=>[n,stats(rows.map(r=>r.gaps2to12[n]))]));
 const by90=rows.filter(r=>r.firstAcceptedSec!==null&&r.firstAcceptedSec<=5400).length;
 policyResults.push({policy,key:policyKey(policy),samples:100,canonical:equal(policy,canonical),firstAcceptedBy90:{reached:by90,samples:100},metrics,milestones,checkpoints,paired8to12,gaps2to12,perSeed:rows});
}
check(report.scenarios.length===9*report.checkpointsMinutes.length,'all policy checkpoint summaries');
for(const scenario of report.scenarios){
 const rs=report.runs.filter(r=>equal(r.policy,scenario.policy));check(rs.length===100&&scenario.samples===100,'scenario denominator');
 const cs=rs.map(r=>r.checkpoints.find(c=>c.minutes===scenario.minutes));
 for(const name of [...firstNames,'lastUnlockSec',...numberFields]){
  const s=stats(cs.map(c=>c[name])),reported=scenario.metrics[name];
  for(const k of ['samples','reached','unreached'])check(reported[k]===s[k],'scenario count '+policyKey(scenario.policy)+'/'+scenario.minutes+'/'+name);
  for(const k of ['p10','p50','p90'])check(reported[k]===s.conditional[k],'scenario conditional '+policyKey(scenario.policy)+'/'+scenario.minutes+'/'+name);
 }
}
const base=policyResults.find(p=>p.canonical),firstMedian=base.metrics.firstAcceptedSec.population.p50,lastMedian=base.metrics.h70EligibleSec.population.p50,by90=base.firstAcceptedBy90.reached;
const goals={firstMedian:{observedSec:firstMedian,minSec:2700,maxSec:3600,passed:firstMedian!==null&&firstMedian>=2700&&firstMedian<=3600},firstDeadline:{reached:by90,samples:100,required:90,deadlineSec:5400,passed:by90>=90},lastMedian:{id:'h70',observedSec:lastMedian,minSec:28800,maxSec:43200,passed:lastMedian!==null&&lastMedian>=28800&&lastMedian<=43200}};
const targetPassed=Object.values(goals).every(g=>g.passed);check(report.targets.passed===targetPassed&&report.targets.samples===100,'canonical100 target verdict only');
const target=id=>report.targets.checks.find(c=>c.id===id);
check(target('first-reincarnation-median')?.observedSec===firstMedian&&target('first-reincarnation-median')?.passed===goals.firstMedian.passed,'reported first goal');
check(target('first-reincarnation-deadline')?.reached===by90&&target('first-reincarnation-deadline')?.samples===100&&target('first-reincarnation-deadline')?.passed===goals.firstDeadline.passed,'reported100 denominator deadline');
check(target('last-unlock-median')?.observedSec===lastMedian&&target('last-unlock-median')?.passed===goals.lastMedian.passed,'reported final goal');
const perPolicyFiles=policyResults.map((p,i)=>({path:output+'/policy-'+String(i+1).padStart(2,'0')+'.json',value:p}));
const destination=output+'/snapshot-complete.json';
if([destination,...perPolicyFiles.map(p=>p.path)].some(existsSync))throw Error('Preserve existing analysis; never overwrite.');
const policyRefs=perPolicyFiles.map(({path,value})=>{writeFileSync(path,JSON.stringify(value,null,2)+'\n',{flag:'wx'});return {path,sha256:fileHash(path),bytes:readFileSync(path).length,policy:value.policy,samples:value.samples,canonical:value.canonical,firstAcceptedBy90:value.firstAcceptedBy90,metrics:value.metrics,milestones:value.milestones,paired8to12:value.paired8to12,gaps2to12:value.gaps2to12};});
const result={schemaVersion:1,kind:'independent-final-v070-release-policy-analysis',agentId:'/root/balance',generatedAt:new Date().toISOString(),analysisGate:'Host COMPLETE then endedAt; all900 before any grouping judgment',executionPath,executionFileSha256:fileHash(executionPath),executionEndedAt:execution.endedAt,reportPath,reportFileSha256:fileHash(reportPath),sourceDigest:report.sourceDigest,evaluationDigest:report.evaluationDigest,protocolPath,protocolFileSha256:fileHash(protocolPath),protocolSha256:report.protocolSha256,rawSha256:report.rawSha256,buildSha256:report.build.sha256,manifest:{path:manifestPath,sha256:fileHash(manifestPath),binding:manifest.binding},experiment:report.experiment,parameters:experiment.parameters,actualSourceParameters:sourceParameters,actualCompiledParameters:compiledParameters,appVersion:'0.7.0',seeds:{start:1,count:100},policyCount:9,totalRuns:900,horizonMinutes:720,archiveInfo,completedDesignBinding:prep.completedDesign,ownedFileManifests:prep.ownedFileManifests,separateOwnedReadme:prep.readmeSnapshot,commands:execution.commands,readinessChecks:execution.readinessChecks,rawFiles,goals,targetPassed,policies:policyRefs,integrity:{status:errors.length?'FAIL':'PASS',errors},populationDefinition:'Each policy100; null after finite; index floor((N-1)*q); worst null if any unreached. Never pool900 for canonical targets.',conditionalDefinition:'Reached-only p10/p50/p90/worst reported separately.',gapDefinition:'Integer100ms, first novel seenHero/seenMonster or chosenHero/killedMonster records within inclusive2h–12h boundaries; no claim this is combat inactivity.',pairedDefinition:'Same seed/same policy8h versus12h checkpoints and post8h actual actions; exact party power strings.',validationResultsForOptimization:false,newNumericalProposal:null,productSourceModified:false,evaluatorModified:false,gameMeasurementExecuted:false,buildExecuted:false,finalAuditExecuted:false,humanChecks:'PENDING',productReleaseVerified:false};
writeFileSync(destination,JSON.stringify(result,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({output:destination,bytes:readFileSync(destination).length,sha256:fileHash(destination),integrity:result.integrity,goals,targetPassed,totalRuns:900,policyCount:9,perPolicyFiles:policyRefs.map(p=>({path:p.path,sha256:p.sha256,bytes:p.bytes}))},null,2));
